esbmc_test_source:
contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Call voteProposal and assert that if it doesn't revert, the returned weight equals
    // the stored per-member vote for this caller and mapPID_votes is updated by
    // removing the old per-member vote and adding the new one.
    function run(uint proposalID) public payable {
        // Read before-values via public getters
        uint beforeTotal = c.mapPID_votes(proposalID); if (__ESBMC_reverted()) return;
        uint beforeMember = c.mapPIDMember_votes(proposalID, address(this)); if (__ESBMC_reverted()) return;

        bool reverted;
        uint returnedWeight;
        // call that may change contract state
        uint256 w = c.voteProposal(proposalID); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
            returnedWeight = 0;
        } else {
            reverted = false;
            returnedWeight = w;
        }

        uint afterTotal = c.mapPID_votes(proposalID); if (__ESBMC_reverted()) return;
        uint afterMember = c.mapPIDMember_votes(proposalID, address(this)); if (__ESBMC_reverted()) return;

        // General rule asserted:
        // If the call did not revert then:
        // 1) the returned weight equals the recorded per-member vote after the call,
        // 2) the total votes were updated by removing the previous per-member vote and adding the new one,
        //    i.e. afterTotal == beforeTotal - beforeMember + afterMember.
        assert(reverted || (returnedWeight == afterMember && afterTotal == beforeTotal + (afterMember - beforeMember)));
    }

    receive() external payable {}
}

