// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DAO} from "../src/DAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DAO c;

    function setUp() public {
        c = new DAO();
    }

    function _run(uint256 proposalID) internal {
        uint256 beforeTotal;
        try c.mapPID_votes(proposalID) returns (uint256 __r) { beforeTotal = __r; } catch { return; }
        uint256 beforeMember;
        try c.mapPIDMember_votes(proposalID, address(this)) returns (uint256 __r) { beforeMember = __r; } catch { return; }
        bool reverted;
        uint returnedWeight;
        try c.voteProposal(proposalID) returns (uint w) {
            reverted = false;
            returnedWeight = w;
        } catch {
            reverted = true;
            returnedWeight = 0;
        }
        uint256 afterTotal;
        try c.mapPID_votes(proposalID) returns (uint256 __r) { afterTotal = __r; } catch { return; }
        uint256 afterMember;
        try c.mapPIDMember_votes(proposalID, address(this)) returns (uint256 __r) { afterMember = __r; } catch { return; }
        assertTrue(reverted || (returnedWeight == afterMember && afterTotal == beforeTotal + (afterMember - beforeMember)));
    }

    function testFuzz_run(uint256 proposalID) public {
        _run(proposalID);
    }

    receive() external payable {}
}
